mapper.sql:
WHERE i.organization_id=#{organizationId}
  AND (a.applicant_cas_id=#{actorCasId} OR #{unrestricted}=TRUE
    OR EXISTS(SELECT 1 FROM project_manager pm
      JOIN organization_member m ON m.id=pm.member_id AND m.organization_id=pm.organization_id
      WHERE pm.organization_id=i.organization_id AND pm.project_id=p.id
        AND m.cas_id=#{actorCasId} AND m.status='ACTIVE'
        AND (m.term_start IS NULL OR m.term_start <= CURRENT_DATE)
        AND (m.term_end IS NULL OR m.term_end >= CURRENT_DATE))
    OR EXISTS(SELECT 1 FROM project_access pa
      JOIN organization_member m ON m.id=pa.member_id AND m.organization_id=pa.organization_id
      WHERE pa.organization_id=i.organization_id AND pa.project_id=p.id
        AND m.cas_id=#{actorCasId} AND m.status='ACTIVE'
        AND pa.access_type IN ('VIEW','REVIEW','MANAGE')
        AND (m.term_start IS NULL OR m.term_start <= CURRENT_DATE)
        AND (m.term_end IS NULL OR m.term_end >= CURRENT_DATE)))


        AND p.id=#{filter.projectId}


        AND af.id=#{filter.formId}


        AND a.applicant_cas_id=#{filter.applicantCasId}


        AND i.invoice_date >=#{filter.invoiceDateFrom}


        AND i.invoice_date <=#{filter.invoiceDateTo}


        AND i.claimed_amount >=#{filter.minClaimedAmount}


        AND i.claimed_amount <=#{filter.maxClaimedAmount}


        AND i.expense_category_item_id=#{filter.expenseCategoryItemId}


        AND i.status IN

            #{status}



        AND EXISTS(SELECT 1 FROM invoice_tag it WHERE it.organization_id=i.organization_id
          AND it.invoice_id=i.id AND it.tag_item_id=#{filter.tagItemId})


        AND i.invoice_type=#{filter.invoiceType}


        AND COALESCE(pi.status,CASE WHEN p.paper_required=FALSE THEN 'NOT_REQUIRED' ELSE 'PENDING_SETUP' END)
          =#{filter.paperStatus}


        AND (i.invoice_code LIKE CONCAT('%',#{filter.keyword},'%')
          OR i.invoice_number LIKE CONCAT('%',#{filter.keyword},'%')
          OR i.digital_invoice_no LIKE CONCAT('%',#{filter.keyword},'%')
          OR i.seller_name LIKE CONCAT('%',#{filter.keyword},'%'))
